  VALUES 
    (11::BIGINT, 'Hasta el momento semana 13 IIS 2026 excelente. El profesor súper excelente, tiene una gran forma de enseñar la materia que es de muy facil comprensión para el estudiantado. El curso se trabaja en excel por lo que si antes del curso no se sabe mucho de excel también se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2026-10-28T00:00:00+00:00'::TIMESTAMPTZ, '5712f4637a57cfc9a258ffe966bfac9be705125da9d11249702fbc8f1f14bef8'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'El profesor domina muy bien la materia y explica con claridad, combinando teoría y ejercicios prácticos. Es respetuoso, puntual y está atento a resolver las dudas. Las evaluaciones son coherentes con lo visto en clase y la retroalimentación ayuda a mejorar. Lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2026-10-23T00:00:00+00:00'::TIMESTAMPTZ, '24e4076667343d82c8efebffcfe87293584b5470c30535fffd292173ed4214bf'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'Explica muy claro y da muchos ejemplos, las clases son largas pero no se sienten pesadas. 2026'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes']::TEXT[], '2026-09-30T00:00:00+00:00'::TIMESTAMPTZ, '8cd6b9a345d59ae6681bbd9e1ab52a9815f03013c8d9fd1ee392c01bfcc384a9'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, brinda mucha ayuda y buena explicación para los temas. Siempre comparte mucho material pero muy útil para los estudiantes para aprender sobre los temas. Súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2026-09-23T00:00:00+00:00'::TIMESTAMPTZ, '3108326ab9057bf9ac63020447fd3d6d0fd634ca05b8b2473425c84302529078'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'Totalmente recomendado, es un profesor que enseña super fácil la materia y los examenes son como las prácticas, si puedes aprovechar matricula con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, '4bd70be4c753aedd782692f81e62e53b765693de90ee9b444927e32505b7a239'::TEXT, ARRAY[3425]::BIGINT[]),
