    (11::BIGINT, 'Muy buen profesor, muy amigable con los estudiantes. A veces las clases se pueden hacer un poco largas, pero enseñando es muy bueno y todo se entiende claro, solo es de prestar atención y no distraerse.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '04a9e13495b663c320cb3e763e793b2ee3410689a84fd0244b3312af87d4bfa4'::TEXT, ARRAY[1782]::BIGINT[]),
