    (11::BIGINT, 'El profesor tiene muchos conocimiento y lo comparte ampliamente con los estudiantes, además siempre está disponible para consultas, hace que las clases sean muy provechosas y promueve la participación activa'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes']::TEXT[], '2026-04-11T00:00:00+00:00'::TIMESTAMPTZ, '5969d0f15d8a7905be9a68c53ae2e705c2a969d9dee3e17aded024080cb37a4b'::TEXT, ARRAY[258]::BIGINT[]),
    (11::BIGINT, 'Profesor que ayuda al estudiante a entender las veces que sean necesarias, la materia es muy sencilla en si pero el la hace más fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-04-10T00:00:00+00:00'::TIMESTAMPTZ, '5bd24b2cfc548ef80a1fa7547b109604a679d749483146037b6411382bb9b6ec'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Gran profesional y persona !'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-03-19T00:00:00+00:00'::TIMESTAMPTZ, '907c19b398a86d0ec3f657b2c9933986f8b546a50774ac3d572596a219e08ba6'::TEXT, ARRAY[1708]::BIGINT[]),
