    (11::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2026-03-01T00:00:00+00:00'::TIMESTAMPTZ, '2aa2fa5ecae465cc4b59255e5b3e84edd92e95cbeaf536252cc30cb6823cce7d'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Es un buen profesor, el cual no se enfoca en que el estudiante se le dificulta el curso, mas bien busca que le sea fácil. Una gran persona. Los que no pasan es porque son demasiado vagabundos, ya que el profe casi regala el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'c6c2bc2adb181387d9da1af88167e2792cfbafaa541110329c9879d3559304d8'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'Muy buen profe se nota que conoce mucho de la materia que da y siempre intenta dar más materia que sea útil para licenciatura o maestría. Sus exámenes son largos, de leer mucho, pero es súper similar a las prácticas hechas en clase. Si tienen consultas es mejor llevarlas a clase o por mensaje'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-28T00:00:00+00:00'::TIMESTAMPTZ, '4b1f8f9e467934de5b7c0bb749ea0d069f41ce792b43b0d6eec290ccd97e375d'::TEXT, ARRAY[2403]::BIGINT[]),
    (11::BIGINT, 'Las clases fueron muy interesantes y amenas. El profesor califica de una forma clara y ordenada. Para los exámenes, hace prácticas y da una buena realimentación del resultado. Tomaría otra clase con este profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-27T00:00:00+00:00'::TIMESTAMPTZ, '73ea6bb7934c3de4536c11836929bad071fedf18548c68a875389ec6166b4382'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'El profe es muy claro, tiene muchísimo conocimiento y además siempre está dispuesto a ayudar entonces es genial llevar cursos con él!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'c964dcf103559c4f752f79158394fe055b26122f6a60a00a715069a3c283d468'::TEXT, ARRAY[3575]::BIGINT[]),
    (11::BIGINT, 'El profe es muy bueno, explica muy bien. Se le nota que le gusta la materia y eso lo transmite. Es muy atento. El mejor profe que tiene la escuela'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, '46779f5859dd94414770064c7c0b5f99138ac57bc343f2822da8d8bb796867f1'::TEXT, ARRAY[2403]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, explica muy bien la materia y motiva al estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-19T00:00:00+00:00'::TIMESTAMPTZ, '3018d09a1f49a46c58c0e82277991037c7bbbc7862f4824a73260616e80b3580'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'De los mejores profes que tuve en el TEC, super pura vida y legalmente sabe mucho del tema que imparte como profesor, ojalá mas profes fueran así, me inspiró a ver si saco mi TFG en finanzas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'ed84ab6a8af6a62326188d4ee565213f52f0fdf91839465f64245e986bbaa2c2'::TEXT, ARRAY[2403]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, gran dominio del tema y del mercado financiero!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2025-10-24T00:00:00+00:00'::TIMESTAMPTZ, '8c430b867fe3c892a95f134e77c69bc674b8834fa622344dfc876155338bdfc3'::TEXT, ARRAY[487]::BIGINT[]),
    (11::BIGINT, 'De los mejores 3 profesores que he tenido en mi vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-10-22T00:00:00+00:00'::TIMESTAMPTZ, '1f975845d81798146768914bec48de7d212dcea852867af66c098657fe08d277'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'Simplemente el mejor profesor del TEC'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-10-22T00:00:00+00:00'::TIMESTAMPTZ, '8fe07acdca4d882494c03217138748b06751bc4d6d2cfb00934b63454ca75643'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'Tiene mucho conocimiento, pero las clases son muy cansadas y largas, explica bien los ejercicios pero falta que el estudiante tenga espacio para realizar más práctica'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2025-10-21T00:00:00+00:00'::TIMESTAMPTZ, 'd3d8be32d25fce72bdd85b8f3ecd1b28430232c5bf72a8c57d946ded674b7a3e'::TEXT, ARRAY[487]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-09-08T00:00:00+00:00'::TIMESTAMPTZ, '8e9cea21f5fbaf665cd2db96a949efc593371aa7c7b6d17c86e021fcf8adb2e5'::TEXT, ARRAY[1527]::BIGINT[]),
    (11::BIGINT, 'excelente docente, muy motivado y muy amable'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'ad97264b7b4b373ada58dcf2871515b02b9e230b5378b6555e35d5cc7d40180b'::TEXT, ARRAY[1527]::BIGINT[]),
    (11::BIGINT, 'Muy amable pero La clase inició de una a ejercicios sin intro peq a tema y luego casos, faltó estructura x eso dudo que los estudiantes hayan aprendido. Es un curso de mate debería parecerse a las clases de mate. llevaba los ejercicios resueltos y los explicaba, solo copiamos fórmulas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2025-07-14T00:00:00+00:00'::TIMESTAMPTZ, '3fab6471139858a4aa91f28ae6e07233ba6ba46fa3ca17d19bcf7a2a186e8ebb'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-30T00:00:00+00:00'::TIMESTAMPTZ, '9915e21f861fd42bee9846ec0f48a09527d0acb89fe15c4fc10bf53fcb5229fd'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'Si tienen la oportunidad de matricular con este profe no la desaprovechen, de verdad se esmera por que los alumnos entendamos la materia y no solo aprendamos para exámenes y ya. Exc profesor lo recomiendo al 100%'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-21T00:00:00+00:00'::TIMESTAMPTZ, '41b762144a0e81cd6282dc283e0bb7b55245b7471c24a9e1e5a78919f9801771'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a5cf5cd935b44f4d9290d78256e4901d0a1b41849ff952d416331925e975a410'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Ya estamos en semana 16 y aún no hemos recibido las calificaciones del TD ni de los proyectos, esto genera mucho estrés porque no saber la nota incluso haciendo un segundo examen no esta bien. Es aquí donde me pregunto hasta donde llega la doble moral? en otro curso piden camara y asistencia y aquí?'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Pocos exámenes']::TEXT[], '2025-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'eeeac427e340f8e6f93de9a631bf71d69e99b73cf0fe42419982554774d2748a'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, no duden en matricular con el.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-15T00:00:00+00:00'::TIMESTAMPTZ, '30df147a96e425c631d19de83a4dc4729da4100d25e7f44c8db04f554577e7a9'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Con él también llevé Administración Financiera I y II y ahorita llevo con él Principios de Inversión. Y es el mejor profesor del mundo mundial. He aprendido muchas cosas y él hace que una le guste y le interese la materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'f6a29acde60a184b0dcc11edb6b00c4675f9111537b63dad7a499c087f367da2'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'El profe es muy atento, le gusta la materia y se nota; da gusto ponerle atención. 2 exámenes y un proyecto. El segundo examen fue en parejas. Una maravilla de electiva.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-07T00:00:00+00:00'::TIMESTAMPTZ, '5a550bb70496417cb2664cb91fb7a34f5bfd22bca6fa8908ec5335e099e1ec0e'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Se ve que conoce de la materia'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-29T00:00:00+00:00'::TIMESTAMPTZ, '1aedc8f4c250a4e2ebcccbd77db6b1d896bad1ee28cb3bf7e68b44fd689b2247'::TEXT, ARRAY[487]::BIGINT[]),
    (11::BIGINT, 'El profesor Manrique cuenta con habilidades de comunicación, métodos de enseñanza pedagógicos, energía positiva contagiosa, dominio del tema… En definitiva, un genio de las finanzas. Dentro de mi carrera estudiantil al grado de Maestría es el mejor educador que he encontrado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'b665b7e54102282c4c3018a99a91ef95baa46b07aaccde27c06f19e1a69ca9b2'::TEXT, ARRAY[487]::BIGINT[]),
    (11::BIGINT, 'Excelente Profesor, se nota su pasion por los temas y por enseñar, aprendi mucho y superó mis expectativas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-29T00:00:00+00:00'::TIMESTAMPTZ, '34c529684dfdde0a4d48ce9ae0d92edc05cdb1b140506134bab6b466014a33d9'::TEXT, ARRAY[487]::BIGINT[]),
    (11::BIGINT, 'Excelente profe, explica todo muy claro y se hace liviana las clases y examenes, se centra mas en que uno aprenda a que uno pase solo los examenes, muy buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-21T00:00:00+00:00'::TIMESTAMPTZ, '5bce56eb49fe7637993a87635ffb400d185212bd644b883f4e930f0e1eaf9f37'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2025-05-21T00:00:00+00:00'::TIMESTAMPTZ, '96657330995ee907fe664e952c5d910c00692785024f9013a878a59146715941'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'Muy buen profesor, conoce mucho de los temas e incluso da ejemplos de la vida real. Sin embargo, me gustaría hacer más ejercicios desde cero en clase para poder practicar más'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-10T00:00:00+00:00'::TIMESTAMPTZ, '95410322a32f8e225a88b3dcc00467edb51cf61475dbe2186a34173ac6e63b41'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Muy buen profesor, explica muy bien, solo em gustaría que pusiera mas casos prácticos para poner en practica toda la materia de clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2025-04-25T00:00:00+00:00'::TIMESTAMPTZ, 'b02d815b7a9d8d36e4ed982ad34238e050475f673c671a856f12fa63755d15a5'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor! Si tienen la oportunidad no la desaprovechen. Nada más que habla muy rápido, pero él no tiene problema en repetirlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2025-04-08T00:00:00+00:00'::TIMESTAMPTZ, '5b976666cd8fe8c55d5e266a8ff48d0b55602e4837dd082b65e8ae100a914814'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'En lo personal, considero su clase muy buena y en si es un profesor de muy buena calidad, el unico problema que le pondria es que considero que necesita ser mas duro en sus clases, poner mas a prueba el conocimiento y forzar a los estudiantes a participar'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-06T00:00:00+00:00'::TIMESTAMPTZ, 'e4a42f548afe62a41c64ef5e2214a5a6938c714db3111c1ee0950211a0f7ca73'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'el profesor demuestra dominio del tema, abarca todos los conceptos del programa con clases magistrales.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-04-05T00:00:00+00:00'::TIMESTAMPTZ, '41029688b7f080beb8ab9c3ed477ac70be1d178309d2f1c7ee3140d05190c06a'::TEXT, ARRAY[356]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, explica con claridad y hace que los temas de inversión sean fáciles de entender y aplicar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-04-05T00:00:00+00:00'::TIMESTAMPTZ, '742673c5b6c0ed0be81d769d0d9dbfb604e97cf8b2881e0376cb448976dd753c'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Buen profe y buenas explicaciones la clase de semana 6 fue la desarrollo muy dinámica e interesante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2025-04-04T00:00:00+00:00'::TIMESTAMPTZ, 'ca4e2db3cd2e37495a2b5cc42f965c265b53aa99c733e394e080b58daefe897c'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Excelente en todo, muchas gracias profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-04-03T00:00:00+00:00'::TIMESTAMPTZ, '6c0f25a6a83251be4adb78f65c042efa9e27deeaeaad532bde03e8bc2ae8d160'::TEXT, ARRAY[1531]::BIGINT[]),
    (11::BIGINT, 'Un dominio excelente de los contenidos, se aprende muchísimo y temas muy útiles. La forma de evaluar es muy objetiva y facilita el aprendizaje'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-03T00:00:00+00:00'::TIMESTAMPTZ, '548c864c74121069b36aa666a53d419dd1011cea11aabf2a3dd5feda4af48f02'::TEXT, ARRAY[356]::BIGINT[]),
    (11::BIGINT, 'El profesor nos comparte casos muy interesantes que hacen super supre dinamicas las lecciones.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-03T00:00:00+00:00'::TIMESTAMPTZ, '3953483b827aa68ce8d34d3bd9b95ba0d8fa75d2e3f9582dc3c09c12faab34a7'::TEXT, ARRAY[356]::BIGINT[]),
