    (11::BIGINT, 'Profesor muy atento a dar recomendaciones y ayudar aún fuera de su horario con tal de cumplir los objetivos de los proyectos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2025-04-01T00:00:00+00:00'::TIMESTAMPTZ, '18c26d92b5870e629233208e4bca38daba04bfe39d707feb3f0c2350005fba68'::TEXT, ARRAY[1531]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-01T00:00:00+00:00'::TIMESTAMPTZ, 'e61225629ceaa8fce71f975294a11afccef456b27d5d0f9cd8b3d551a7cab26f'::TEXT, ARRAY[258]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, no duden en matricular con el, sumamente amable, las clases súper claras brindando el material que el explica entonces puedes entender al 100% cada paso, brinda mucho apoyo académico, excelente persona y profesional una suerte tenerlo de profesir'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-30T00:00:00+00:00'::TIMESTAMPTZ, 'd5aac4fe0f99f3d988ea02e9e2ab58b6b1c38acb47b9f318679886344d805f87'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'El profe muestra temas y nos proporciona información muy muy interesante sobre el tema en cuestión, son bastantes lecturas eso sí pero si se llevan al día resulta bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2025-03-29T00:00:00+00:00'::TIMESTAMPTZ, '88b60ee4c82ce070447c4b2fff503cce591c461379fa7c7005053d4c1bdb6c1a'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-29T00:00:00+00:00'::TIMESTAMPTZ, 'ef8bb13f23d90cf6f90b53313deb2af5ff3274e269a418392d47d656a82e0fc6'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Clases largas']::TEXT[], '2025-03-27T00:00:00+00:00'::TIMESTAMPTZ, '73eec94712097d9e5122139059f33b4cf8d0bb200186f9f7fac75dae50d182cf'::TEXT, ARRAY[356]::BIGINT[]),
    (11::BIGINT, 'muy conciso en sus explicaciones'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-26T00:00:00+00:00'::TIMESTAMPTZ, '30edd246a9c53165581d8f588a026524bd21909fce5ca6c3528a7df425fe2329'::TEXT, ARRAY[356]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor con un gran dominio del tema, no solo agarra los ejercicios del libro sino que les agrega variedad a los casos y siempre nos comparte las respuestas lo cuál me parece super importante ya que nos permite identificar donde nos equivocamos. Además da espacios para discusión.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-03-25T00:00:00+00:00'::TIMESTAMPTZ, '7eabe7f462ebea3f7c9f1af38467007f8c7f6b5581a82d3a38a4e24a48d8d6e2'::TEXT, ARRAY[356]::BIGINT[]),
    (11::BIGINT, 'Es un excelente profesor, si uno sabe cómo llevarlo la pasa súper bien, toma su tiempo para todo y espacio lo que hace que sea más asertivo con la materia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-22T00:00:00+00:00'::TIMESTAMPTZ, '5a68f835ef64b18bde0f85a0b0ac7ff6311c79256fe9e292a7ff2b5d836ef71c'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'La interacción con los estudiantes es plena y asertiva, eso hace que las clases sean interesantes y fácil de comprender. Aunado a ello, le permite al estudiantado comprender la materia y aceptar mucho más la vocación de la carrera en curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-03-19T00:00:00+00:00'::TIMESTAMPTZ, '55a623941092bc2e956de5ca326993b77ec85b46ef60db678faf787cf795485c'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Mucha capacidad por parte de este profesor... 10/10 definitivamente, solo me hacen falta las tildes en las presentaciones a veces, pero lo demás muy bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes']::TEXT[], '2025-03-18T00:00:00+00:00'::TIMESTAMPTZ, 'fe8eaf7631fcaa34d5d50157cffb803e6a95f402b668029ee2f099e1b5c3e2b5'::TEXT, ARRAY[356]::BIGINT[]),
    (11::BIGINT, 'La metodología es bonita, el profe explica detalladamente a cada estudiante hasta que no le queden dudas, ahorita estoy en semana 4 con él y hemos aprendido despacio pero todo de muy buena manera, te comprende como estudiante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-13T00:00:00+00:00'::TIMESTAMPTZ, 'b108a0219fcee158ff342a7623bb0382b182d32f954d2873902ba89fe4e04b3f'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, las clases son muy entretenidas, además explica muy bien y es muy amable. No duden en matricular con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-13T00:00:00+00:00'::TIMESTAMPTZ, '7e67fef93b8a1b2f558bf2ff6b94ef69eaaa64b0aa4658033533b15474ac5766'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Las clases son muy amenas, se explica con ejemplos fáciles de entender. Estoy empezando el curso pero me parece un buen profesor. Cuesta mucho que conteste los correos electrónicos'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-13T00:00:00+00:00'::TIMESTAMPTZ, '00b5ef527efd4ed4a39234cc1781c538d5c481e5b06d5419c340e253e73bc20d'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'El profesor Manrique demuestra un basto conocimiento en el tema de Inversión y hace la clase entretenida. He notado empatía con nosotros los estudiantes lo cual es algo importante para mí. De momento llevamos 3 clases así que no puedo opinar mucho ya que es la primera materia que llevo con él. FSE'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2025-03-13T00:00:00+00:00'::TIMESTAMPTZ, 'f06283c22d6a3bab01cc1a0c44be5f5f4708fed3c9d67fd4bf369db93842e6c6'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Las clases podrían tener más estructura, resolver ejercicios en clase debe ser primordial, ver los ejercicios resueltos puede hacer que los estudiantes pierdan interés "porque ya está resuelto". Las horas de clase se podrían aprovechar un poco mejor.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2025-03-12T00:00:00+00:00'::TIMESTAMPTZ, '784905c3fb0e4a94e5ac4752215780c6c942afa7b78367ef16d3bb178da9b160'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2025-03-12T00:00:00+00:00'::TIMESTAMPTZ, '0b322e58582745b4d7a6cba823a39949247b861852caf80f991a2961dc50f666'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Honestamente, creo que es demasiado prematuro opinar con solo 4 semanas en este curso, sin embargo, en estas semanas he aprendido entre poco y nada. En 2 clases hemos abarcado 1 solo tema, y en una explicó un solo ejercicio. Recomendaría menos anécdotas, y clases más explicativas, con más ejercicios'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2025-03-12T00:00:00+00:00'::TIMESTAMPTZ, '3dfaf543e6144d84abe38b07673b37c0a4494208b2d25934e0c3ded65d3efb12'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-03-12T00:00:00+00:00'::TIMESTAMPTZ, '05b0180b5e7d106fb9527b71769d6676d929e54ecd17d149eca5a515f69e3b64'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Solo lo conozco de las 4 semanas que he recibido clases con él en Principios de Inversión el primer semestre de 2025, pero de momento me parece un muy buen profesor, explica muy bien, y tiene buen trato hacia los estudiantes. Buen carisma. Para efectos del curso si nos envía mucho a ver documentales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-03-11T00:00:00+00:00'::TIMESTAMPTZ, '1559421b0dc6dd0c8f8891550348968ed4abe9282ca066b23b7b5f32d79bfa83'::TEXT, ARRAY[3426]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, explica super bien y aclara las mil y una duda que pueda surgir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2025-03-11T00:00:00+00:00'::TIMESTAMPTZ, 'a8134aa9552a4b549876fa53af65b0cdc25805b4f0a61ef5737694b735661a4d'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'Es un gran profesor, sus clases son muy entretenidas y nos cuenta anécdotas muy interesantes que ayudan a comprender mejor la materia, sus clases no se hacen largas y siempre esta dispuesto a hacer lo posible por dar un buen ambiente académico.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-09T00:00:00+00:00'::TIMESTAMPTZ, '6165f96f4f0a47b1f4e7a4221dd84777efd913ae5bac37b6bec85d38d0de3726'::TEXT, ARRAY[1708]::BIGINT[]),
    (11::BIGINT, 'El mejor profesor que he tenido en el area de finanzas, solo que explica muy rapido y no da chance de apuntar todo lo que dice, tiene mucho conocimiento y sus anecdotas son interesantes, solo que si me gustaria que explicara mas lento y con un mayor grado de detalle'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2025-03-08T00:00:00+00:00'::TIMESTAMPTZ, 'd528b34916d0eafeda6fd8b981fa51371de8cc5952a5ad00335ca0c5cd0b4122'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'El profe es muy bueno pero habla muy rápido y cuesta entenderle a veces lo que dice por eso'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-08T00:00:00+00:00'::TIMESTAMPTZ, 'a9c3fe474f8911f55ec68ad9eef970783b685683ddfb7fbcb3b677807e3771f2'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'Las clases son interesantes, el profesor explica bien, sus anécdotas son entretenidas y útiles porque tienen que ver con el tema en clase, y no es una clase aburrida. Se preocupa por los estudiantes y es muy flexible. Si tienen la oportunidad de matricular con él, háganlo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-08T00:00:00+00:00'::TIMESTAMPTZ, 'd9944cce2ecbfd9c6d0096281f90973a177f4910e236d6058f9724af5f87cd0f'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'Las clases son buenas y se entiendemuy bien. Sin embargo, sería mejor en otra aula o donde se pueda proyectar de mejor manera las presentaciones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-08T00:00:00+00:00'::TIMESTAMPTZ, '040e72058a3d2d0068b93567a8bb22fda80422c897b43afd5567cb7ae736774e'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'En general la materia se entiende, me gustaría ver un poco más de conceptos de fondo a los cálculos que se hacen. Por otro lado, me gustaría tener una mayor claridad respecto a las expectativas del proyecto final de curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-03-06T00:00:00+00:00'::TIMESTAMPTZ, '2dbd6f2648a6d481e1f63fe30d92207a5ef90966d610b4ba7159bf72869861f8'::TEXT, ARRAY[356]::BIGINT[]),
    (11::BIGINT, 'Se nota que sabe mucho del tema, es un buen profe en general, lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-05T00:00:00+00:00'::TIMESTAMPTZ, '66849fd9937fa61fb60ac5fccb15e22233e0865c6fa05b73f4a07a07cb999135'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'S2: No me gusta la metodología. Al tratarse de mate uno necesita saber xq se hacen las cosas, no solo copiar fórmulas en Excel. Me gustaría que explicara el tema en la pizarra, explicar xq la fórmula es de tal forma y como se hace a mano, ya luego pasar al Excel, así se aprende de verdad el tema.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-03T00:00:00+00:00'::TIMESTAMPTZ, 'c779dfe6c5db4dc07f0aa89b7725d7f2f038376656b2928fee2a30421ede1222'::TEXT, ARRAY[1708]::BIGINT[]),
