    (11::BIGINT, 'Profesor muy atento ayudar, ilustra muy bien los temas, dando ejemplos claros.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-16T00:00:00+00:00'::TIMESTAMPTZ, '10384541637e4ad2626f9601c9c67aae4a660b088c9d187dee7b28c9ec7cafe4'::TEXT, ARRAY[1530]::BIGINT[]),
