    (11::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, 'b0abb3dd3c9841645a4fa2feba245fd1ce77666b22509dcdbc232e9791daf00f'::TEXT, ARRAY[258, 1530]::BIGINT[]),
    (11::BIGINT, 'Toda la información muy clara, una persona respetuosa y amable, con una alta disposición para todos los grupos para atender dudas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, 'cc37b83bd446c1dc9f58aafd58e05188b3d8e97e8efe1de887b379a641d39c76'::TEXT, ARRAY[1530]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, '599d6747711f8322bb6d7afe345b08cdde77f8e0ca880ecd973a27a78f14e66e'::TEXT, ARRAY[1530]::BIGINT[]),
    (11::BIGINT, 'Excelente manera de explicar, disfruta lo que hace y lo transmite a los estudiantes, las clases quizá pueden resultar un poco largas, pero para los que nos gusta el área de finanzas resulta muy provechoso todo lo que el profe explica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'dd21769e6dfd4a3501c78fef9b18b10103da8cce74faf3d16c2b00419dc077c3'::TEXT, ARRAY[3575]::BIGINT[]),
    (11::BIGINT, 'Realmente es un profesor con el que uno debe estar pendiente de lo que dice, por lo general da una clase virtual antes del examen donde resuelve exámenes viejos y da toda la explicación necesaria. Los exámenes son muy parecidos a lo que el explica la clase previa al examen y realmente ayudan mucho.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-22T00:00:00+00:00'::TIMESTAMPTZ, '60747bc1ec4654e86779bbbf9c04a57367081d4d30f943d503f0f8e76b9cf5a2'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'El profesor es excelente como profesional y como persona. El TEC está repleto de profesores que pueden llegar a ser unos patanes y llenos de sí, pero puedo asegurar que el profesor Manrique no es uno de ellos. Se pone en los zapatos de los estudiantes, y eso le hace ganarse el respeto de todos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-11-20T00:00:00+00:00'::TIMESTAMPTZ, '0eb9a551e133b13e27fb40947a717cb1b7804b290441993bf698d336560e864f'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'Da ejemplos muy claros y adaptados 100% a la realidad. Se preocupa porque los estudiantes entiendan la materia y crea un ambiente de confianza para participar y hacer consultas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-20T00:00:00+00:00'::TIMESTAMPTZ, '67a7a8b457e9b646763687a8c8544f611b95099a8a83b5b1a9a2d8916b8abc6f'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, las explicaciones y el conocimiento le permiten hacer ver las cosas fáciles. Super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f70b07cec78dda19ff5030ebc97722fb6c30bb0ffa2204ec113e394cd795f16a'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'El profesor hace la clase amena, y los temas que son muy importantes e interesante para la vida y la profesión, utiliza la anecdota para explicar casos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-11-15T00:00:00+00:00'::TIMESTAMPTZ, '3fb2f9ef2902da161547d1d180640fc5f6b232275a871eee120b302ab240bc16'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, se aprende mucho. Hay que estar muy concentrado porque habla muy rápido. Le gusta lo que enseña y tiene mucho conocimiento. Si puede lleve materias con él.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-12T00:00:00+00:00'::TIMESTAMPTZ, '27f60897ed697ea506e47b45da281ff6e25e43d3d64ffb1cd7ad80c3feca3e15'::TEXT, ARRAY[1782, 2403]::BIGINT[]),
    (11::BIGINT, 'Excelente profe, es muy relajado y comprensivo, no lo piense y matricule con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, '9ae3f46f22f0d5c27e596f1d31489a617f121def10ea34e67ca89299e5dcde00'::TEXT, ARRAY[2403]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, '667495a2e56b58f00d0b571542d9bad07d5723c7716b1491797a228e69d581f8'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'Sin lugar a dudas de los mejores profes del TEC, cuenta con bastos conocimientos de la matería y tiene mucha paciencia y facilidad para enseñar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, '2522a60e929939d46aec73c8d64f106ed59a0d05fb367b861a9601bc78103121'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'De lo mejor !!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, '134d5b0cdae3498aac4328b37301f91b3f238b1fe66c78906a04c6fdd996aa2d'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'TFG caro vs recursos que se brindan. Las tesis de MSc en promedio son menores de 100 páginas en todas las ramas, este TFG se extiende a 200 o más, un absurdo, deben reformular su estructura. Nadie se lee los 50 libros que propone en 6 sem. Recordar que no está formando investigadores en este curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2024-10-27T00:00:00+00:00'::TIMESTAMPTZ, 'bd6e6f313f40aabf976639201888fcb0fbf5cbca598e1cf9db016912a4619d48'::TEXT, ARRAY[1531]::BIGINT[]),
