    (11::BIGINT, 'Muy clara la visión y modo de dirigir la clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2024-10-21T00:00:00+00:00'::TIMESTAMPTZ, 'df2b5bb86bc0bbe10aaac2fc335a5500f1df3c7f245598e31b1f5602321f4281'::TEXT, ARRAY[258]::BIGINT[]),
    (11::BIGINT, 'Profesor muy capacitado. Mí hubiera encantado recibir una clase académica con él ya que he se nota que tiene mucho conocimiento. Durante el seminario mostró una serie de conocimientos que inspiran en definitiva querer seguir adelante con los estudios.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2024-10-19T00:00:00+00:00'::TIMESTAMPTZ, 'c7ef723d8759125c3ea119e4b4924e39f5da73696eb6db6788fae6e1f145eedd'::TEXT, ARRAY[258]::BIGINT[]),
    (11::BIGINT, 'El profe siempre esta muy anuente a ayudar y atenderlo a uno cuando necesita, sin importar la hora ni el día, esto ayuda mucho ya que siempre tiene buena actitud. Muchas gracias por su paciencia y ayuda profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2024-10-16T00:00:00+00:00'::TIMESTAMPTZ, 'e0b1eb4ca97ff78565d644f191422f08cb7b1de51ceca178fec664ecb5f0d68c'::TEXT, ARRAY[4422]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-10-15T00:00:00+00:00'::TIMESTAMPTZ, '1463deab0ecc1bd78c1338bd840b1ec8abfc274439bced770d911a57de5e0dc7'::TEXT, ARRAY[1530]::BIGINT[]),
    (11::BIGINT, 'Es un excelente profesor, explica con mucha claridad, da prácticas para los exámenes y atiende dudas con mucha paciencia. El proyecto puede que lo explique un poco tarde en el curso pero de igual manera lo explica con mucha claridad.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-06T00:00:00+00:00'::TIMESTAMPTZ, '8adc5c68e421ff1480bdb9f784f53ed289a2c6c9a3ebdc53a4aadcf2e00a8877'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'Si tiene la oportunidad de matricular con él hágalo, es el mejor profesor que va a encontrar en el sector de finanzas, el 1 examen siempre es un poco largo pero si se prepara bien le va a ir bien , además deja mucha practica de examen, 100 recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-04T00:00:00+00:00'::TIMESTAMPTZ, '37d182b577575800ea9f39be48db5bde12d2b59ec92b7d58dda332b9daf1c6fa'::TEXT, ARRAY[2403]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor, sabe mucho del tema y se nota que ama lo que hace. Muy comprensible y dispuesto a ayudar al estudiante. Da clases virtuales y presenciales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2024-10-04T00:00:00+00:00'::TIMESTAMPTZ, '725034e4bea1d5c23edfd9ba02c581d0a3078f564f3edbc0b4312497aa0199fd'::TEXT, ARRAY[2403]::BIGINT[]),
    (11::BIGINT, 'El curso ha sido muy ameno de llevar, ya que se nota el interés del profesor en la materia y que los estudiantes aprendan.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-03T00:00:00+00:00'::TIMESTAMPTZ, '5ddcad3c0fdb414ea60962ac90a6e279ab4e8211453c5925022058b5cce2b5ea'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'Es buen profe, tiene muy buena actitud y sabe mucho sobre la materia que imparte. Sin embargo, considero que hace las clases extremadamente largas y muy poco dinámicas.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-09-27T00:00:00+00:00'::TIMESTAMPTZ, '21a69fcc1f92dc1a3473aa2be55f79c37d04f230a8b56cdc296036ac9e926e6d'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-09-27T00:00:00+00:00'::TIMESTAMPTZ, 'f33e502e8fae04c72007d5306b8b7ffa260ece651e1bf2e78fbc99536d8c5b69'::TEXT, ARRAY[3575]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-09-24T00:00:00+00:00'::TIMESTAMPTZ, '9cfad9a1360a4908e9993009301c2e42d615cdf98f5e9fe6f7fd6f28e411189a'::TEXT, ARRAY[487]::BIGINT[]),
    (11::BIGINT, 'Excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-09-23T00:00:00+00:00'::TIMESTAMPTZ, 'bec57251bf486c03184b37e1c975a3b6e3b86cc165136037ace5147f2557436b'::TEXT, ARRAY[2403]::BIGINT[]),
    (11::BIGINT, 'Demuestra un conocimiento amplio y profundo de temas complejos pero también una habilidad importante para transmitir este conocimiento y animar al estudiante para querer aprender más.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2024-09-23T00:00:00+00:00'::TIMESTAMPTZ, '67abdadca24b17cd9a77e27b7cb12b29ca71600d0e89580ed94b97371fcc6041'::TEXT, ARRAY[487, 482]::BIGINT[]),
    (11::BIGINT, 'Es un excelente profesor, sabe mucho sobre Finanzas, enseña y se preocupa porque sus estudiantes aprendan.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-09-22T00:00:00+00:00'::TIMESTAMPTZ, 'df728f6f5182bcf4c0b26cd6e935ac4631a9359866b14b845dd577ecf2462a6f'::TEXT, ARRAY[1782, 2403]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2024-09-22T00:00:00+00:00'::TIMESTAMPTZ, '11d855403d072c2d589b17bc67199b5c5813aec75166f49d311d21eb5fb2a7b2'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-09-21T00:00:00+00:00'::TIMESTAMPTZ, '7f05d3fca7200ef450400e848bc11d03436fc7eb32bceff331824805979b0a5b'::TEXT, ARRAY[487]::BIGINT[]),
    (11::BIGINT, 'Este curso es el más pesado de la carrera, y pese a todo lo recomiendo a el, pocos profesores saben dar este curso y a como lo ha hecho el me quito el sombrero'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas']::TEXT[], '2024-09-21T00:00:00+00:00'::TIMESTAMPTZ, 'dc60350a770e5805991481b00c0f952e99ebc1ee8649299d82b1e498ea815213'::TEXT, ARRAY[1782, 2403]::BIGINT[]),
    (11::BIGINT, 'Es muy claro al explicar, da ejemplos de la vida real, cuenta historias cómicas, es buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-09-21T00:00:00+00:00'::TIMESTAMPTZ, '4354e6d150c05634b4e4bd1245efbc5a399b88134ac6906ac79cea85ce50a190'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2024-08-22T00:00:00+00:00'::TIMESTAMPTZ, '86df213dbeaa8ec15536bcfce67e5a3b14f6a557633f193d188c18c7455676eb'::TEXT, ARRAY[1530]::BIGINT[]),
    (11::BIGINT, 'El mejor profesor que he tenido en toda la carrera, da un gusto escuchar su clase, sabe de lo que habla y un poco más, hasta los profesores llegan a hacerle consultas académicas durante el curso.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'acf0b868e696c775a5759eb7203ff99f5eaefdd47f01b136366448d17e3a5711'::TEXT, ARRAY[2403]::BIGINT[]),
    (11::BIGINT, 'Si todos los profesores fueran como él seria un éxito, la verdad explica los temas de muy buena manera y es un profesor que se acopla muy bien a la modalidad virtual y bimestral. la materia queda super clara.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2022-12-15T00:00:00+00:00'::TIMESTAMPTZ, '4e55e56f42c891ce06f0f9fa6acffc6e2f257364173f59c89d073df996af5da7'::TEXT, ARRAY[293]::BIGINT[]),
    (11::BIGINT, 'Es un excelente profesor, explica muy bien. Lo único que no me gusta es que es un poco desordenado con las evaluaciones. Pero en general es de los mejores profesores de la cátedra, súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, '8074c4921de2a48ec21a611fd24b4b120518ccf6a677600f73d6c4050c3ea675'::TEXT, ARRAY[1782]::BIGINT[]),
    (11::BIGINT, 'El mejor profe de la virtualidad. Exámenes sumamente fáciles, deja una práctica muy similar antes de cada parcial. Uno de verdad aprende y el profe transmite una actitud muy positiva al curso, super recomendado 1000000/10 x2'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '2fcf47f0081c4a0e07463e43544d9d52ef4781dc0255e2ff1a0f226bdb34c32e'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'Explica claro la materia, se le entiende perfecto y busca que las personas aprendan. Si puede matricular con él hágalo, ya que de verdad se aprenden muchas cosas útiles para la vida profesional y personal. En general excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '32eaba132ad273b5e724db65a13fcd493a8f37b2b9f8d9dc7de032595a76a0dd'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'Es súper tuanis, todo se entiende muy bien y el curso es súper fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'd8e0b9c7eb88304c5f72359e78c6049c4dc5f8290276c36fadabc90e4c56636b'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'De los mejores profesores del TEC. Sabe muchísimo y lo demuestra. Siempre está dispuesto a ayudar y le importa que el estudiante aprenda más allá de una nota. Es un excelente profesor, inspira a mejorar. De verdad vale la pena llevar cursos con él. Uno de verdad aprende y él da todo el material.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '6b86f8c459d1437a77107ffb98f6568289c0a365dc8f85192e666f72bfd1666a'::TEXT, ARRAY[2403]::BIGINT[]),
    (11::BIGINT, '[virtual] Los exámenes son súper fáciles, hace una práctica casi igual al examen en la clase anterior. Super buena gente, no importa si tiene que explicar un tema 3 o 4 veces'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '299e808b05c20ca382dbbca1c2ea67a7a96551caa24976dfcf4d36c2cc6e61b1'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'Excelente profe, no lo dude para matricular con él, es muy bueno para dar su clase, siempre subo el excel de lo que hace en clase, se ve que sabe mucho más que lo que da en el curso, los examenes son en excel, y las tareas y el proyecto en excel y en grupo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, '3fd700c8f23dec5370cf0f62a27f135ee346e8f6dc4b41fa7c33004ae40ac542'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'El profe es super pura vida, los examenes son con excel y todo se ve en clases. Las tareas y el proyecto son grupales. Super recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2019-12-17T00:00:00+00:00'::TIMESTAMPTZ, '265591a1b00ed6995ae5ecdc6f7fdbd61589f1a7b671dc7da715a8db031eec3e'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'Muy bueno y se pasa fácil, solo es asistir a clases porque se entiende muy bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '18e99a69bc6b9d5e05187e070dc3b748a713e64ad45cf3e33a9f183a1792d9d9'::TEXT, ARRAY[1298]::BIGINT[]),
    (11::BIGINT, 'Buena explicación, enfoque a finanzas aplicadas afuera, no hay quices, las tareas son grupales, se puede usar Excel en los exámenes, el proyecto es un caso planteado por el profesor. Explica temas fuera de la evaluación del curso de mayor alcance a los temas del plan. Muy recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-10-31T00:00:00+00:00'::TIMESTAMPTZ, 'f3383579ea3b1380bc83b1bbe815f6cf9e77f017b4dec0558a765a591ae857c3'::TEXT, ARRAY[1298]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
